import re,glob,statistics as st,sys
from datetime import datetime
ansi=re.compile(r'\x1b\[[0-9;]*m'); leg=sys.argv[1]
def ts(s): return datetime.strptime(s[:26],'%Y-%m-%dT%H:%M:%S.%f').timestamp()
rows=[]
for f in glob.glob(f'{leg}/node*-el.log'):
    prev=None
    for l in open(f,errors='replace'):
        if 'Block added to canonical chain' in l and 'txs=163000' in l:
            t=ts(ansi.sub('',l));
            if prev: rows.append((t,'cycle',t-prev))
            prev=t
        elif 'handed to the engine as executed' in l and 'txs=163000' in l:
            l=ansi.sub('',l); kv=dict(re.findall(r'(\w+)=(\d+)',l)); rows.append((ts(l),'import',int(kv['total_ms'])/1000))
if rows:
    t0=min(r[0] for r in rows); out=[]
    for b in range(0,150,15):
        sel=[r for r in rows if b<=r[0]-t0<b+15]
        def med(k):
            v=[r[2] for r in sel if r[1]==k]; return f'{st.median(v):.2f}' if v else '-'
        out.append(f't+{b}:{med("cycle")}/{med("import")}')
    print(leg.split('/')[-1], 'cycle/import over time:', ' '.join(out))
PYEOF
  echo "$tag verify: $(F7_NODES=3 F7_HTTP_BASE=8700 timeout 60 python3 scripts/fleet7-verify.py --window 32 --settle 2 --json $B/bench-$tag/verify.json 2>&1 | tail -1)"
  for p in $(pgrep -f '/n4[2] node --chain'; pgrep -f 'h2_validato[r]'; pgrep -f 'tx_floo[d]'); do kill -9 $p 2>/dev/null; done; sleep 2
}
leg() {
  if [ $(( $(date -u +%s) - CLAIMED_AT )) -gt 4500 ]; then echo "leg loop256$1 skipped: 75 minutes of the claim used"; return; fi
  local tag=$1; shift
  run loop256$tag F7_EL_EXTRA="--builder.interval 60 --builder.deadline 3" N42_FAST_TRANSFER=1 N42_FOLLOWER_DIRECT_IMPORT=1 F7_SENDER_CACHE_MULT=4 N42_TX_QUEUE_BATCH=1024 N42_TX_QUEUE_DRAINER=1 F7_FLOOD_WINDOW=6 N42_TX_INGEST_RECOVER_PARALLEL=12 F7_BLOCK_INTERVAL_MS=350 "$@"
}
C='N42_BUILDER_PULLER=1024 N42_TX_QUEUE_RUN=64 MALLOC_CONF=thp:always N42_FOLLOWER_PARALLEL=1 TOKIO_WORKER_THREADS=8 F7_FLOOD_ALG=ed25519 N42_ALTSIG_SENDER_CACHE=4194304 N42_ED25519_BATCH=128'
R='N42_PARALLEL_BUILD=1 N42_FOLLOWER_GRAFT=1 F7_STRAGGLER_GRACE_MS=600 RAYON_NUM_THREADS=16 N42_BUILD_ON_SEAL=1 F7_LEADER_TENURE=64 N42_QMDB_RETAIN_DEPTH=16 N42_QMDB_ENTRY_FILE=1'
A2='MALLOC_CONF=thp:always,oversize_threshold:0,dirty_decay_ms:2000,background_thread:true'
D='N42_QMDB_READS=on N42_HASHED_TABLES=off F7_BLOCK_INTERVAL_MS=275 F7_GASPRICE_ARG=1000000000000000000000000 F7_SENDER_CACHE_MULT=1'
leg SIMDa F7_BIN=$SIMD $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full" N42_BUILD_CHAIN=1 N42_COMMIT_FCU_ASYNC=1 N42_BODY_ONCE=1 F7_BENCH_POOL_SLOTS=652000 F7_BLOCK_INTERVAL_MS=175 N42_FOLLOWER_PARTITION_HASH=1 N42_FOLLOWER_FREE_ASYNC=1 F7_LEADER_TENURE=256 F7_PERTX_ARG=32000 N42_BLOCK_BY_DESCRIPTION=1 N42_BUILD_COLLECT_IN_PLACE=1 N42_BUILD_ON_OUTPUT=1 N42_SEAL_AT_EXEC=1 N42_STATE_AFTER_PULL=1 N42_FOLLOWER_PARTITION_AHEAD=1 N42_ENGINE_TAKE_SEALED=1 TOKIO_WORKER_THREADS=16 N42_BUILD_START_ASYNC=1 F7_BLOCK_INTERVAL_MS=125 F7_BENCH_POOL_SLOTS=1000000 F7_FLOOD_RATE=950000 F7_LEADER_TENURE=1024 N42_TENURE_FIRST_ON_OUTPUT=1
leg NATc F7_BIN=$NAT $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full" N42_BUILD_CHAIN=1 N42_COMMIT_FCU_ASYNC=1 N42_BODY_ONCE=1 F7_BENCH_POOL_SLOTS=652000 F7_BLOCK_INTERVAL_MS=175 N42_FOLLOWER_PARTITION_HASH=1 N42_FOLLOWER_FREE_ASYNC=1 F7_LEADER_TENURE=256 F7_PERTX_ARG=32000 N42_BLOCK_BY_DESCRIPTION=1 N42_BUILD_COLLECT_IN_PLACE=1 N42_BUILD_ON_OUTPUT=1 N42_SEAL_AT_EXEC=1 N42_STATE_AFTER_PULL=1 N42_FOLLOWER_PARTITION_AHEAD=1 N42_ENGINE_TAKE_SEALED=1 TOKIO_WORKER_THREADS=16 N42_BUILD_START_ASYNC=1 F7_BLOCK_INTERVAL_MS=125 F7_BENCH_POOL_SLOTS=1000000 F7_FLOOD_RATE=950000 F7_LEADER_TENURE=1024 N42_TENURE_FIRST_ON_OUTPUT=1
leg SIMDb F7_BIN=$SIMD $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full" N42_BUILD_CHAIN=1 N42_COMMIT_FCU_ASYNC=1 N42_BODY_ONCE=1 F7_BENCH_POOL_SLOTS=652000 F7_BLOCK_INTERVAL_MS=175 N42_FOLLOWER_PARTITION_HASH=1 N42_FOLLOWER_FREE_ASYNC=1 F7_LEADER_TENURE=256 F7_PERTX_ARG=32000 N42_BLOCK_BY_DESCRIPTION=1 N42_BUILD_COLLECT_IN_PLACE=1 N42_BUILD_ON_OUTPUT=1 N42_SEAL_AT_EXEC=1 N42_STATE_AFTER_PULL=1 N42_FOLLOWER_PARTITION_AHEAD=1 N42_ENGINE_TAKE_SEALED=1 TOKIO_WORKER_THREADS=16 N42_BUILD_START_ASYNC=1 F7_BLOCK_INTERVAL_MS=125 F7_BENCH_POOL_SLOTS=1000000 F7_FLOOD_RATE=950000 F7_LEADER_TENURE=1024 N42_TENURE_FIRST_ON_OUTPUT=1
leg SIMD1000 F7_BIN=$SIMD $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full" N42_BUILD_CHAIN=1 N42_COMMIT_FCU_ASYNC=1 N42_BODY_ONCE=1 F7_BENCH_POOL_SLOTS=652000 F7_BLOCK_INTERVAL_MS=175 N42_FOLLOWER_PARTITION_HASH=1 N42_FOLLOWER_FREE_ASYNC=1 F7_LEADER_TENURE=256 F7_PERTX_ARG=32000 N42_BLOCK_BY_DESCRIPTION=1 N42_BUILD_COLLECT_IN_PLACE=1 N42_BUILD_ON_OUTPUT=1 N42_SEAL_AT_EXEC=1 N42_STATE_AFTER_PULL=1 N42_FOLLOWER_PARTITION_AHEAD=1 N42_ENGINE_TAKE_SEALED=1 TOKIO_WORKER_THREADS=16 N42_BUILD_START_ASYNC=1 F7_BLOCK_INTERVAL_MS=125 F7_BENCH_POOL_SLOTS=1000000 F7_FLOOD_RATE=1000000 F7_LEADER_TENURE=1024 N42_TENURE_FIRST_ON_OUTPUT=1
cleanup
echo "released at $(date +%H:%M)"
echo ALLDONE
